const countVehicleAnomalyEpisodes = `-- name: CountVehicleAnomalyEpisodes :many
WITH totals AS (
    SELECT
        anomaly_code,
        count(*) FILTER (WHERE opened_at >= $1::timestamptz AND opened_at < $2::timestamptz) AS opened,
        count(*) FILTER (WHERE opened_at < $2::timestamptz AND (closed_at IS NULL OR closed_at >= $2::timestamptz)) AS open_at_to
    FROM vehicle_anomaly_episode_view
    WHERE ($3::bigint IS NULL OR server_id = $3::bigint)
      AND ($4::bigint IS NULL OR agency_id = $4::bigint)
      AND opened_at < $2::timestamptz
      AND (closed_at IS NULL OR closed_at >= $1::timestamptz)
    GROUP BY anomaly_code
),
closed_counts AS (
    SELECT
        anomaly_code,
        close_reason,
        count(*) AS closed
    FROM vehicle_anomaly_episode_view
    WHERE ($3::bigint IS NULL OR server_id = $3::bigint)
      AND ($4::bigint IS NULL OR agency_id = $4::bigint)
      AND closed_at >= $1::timestamptz AND closed_at < $2::timestamptz
      AND close_reason IS NOT NULL
    GROUP BY anomaly_code, close_reason
)
SELECT
    vat.anomaly_code,
    COALESCE(totals.opened, 0)::bigint AS opened,
    COALESCE(totals.open_at_to, 0)::bigint AS open_at_to,
    closed_counts.close_reason,
    COALESCE(closed_counts.closed, 0)::bigint AS closed
FROM vehicle_anomaly_type vat
LEFT JOIN totals ON totals.anomaly_code = vat.anomaly_code
LEFT JOIN closed_counts ON closed_counts.anomaly_code = vat.anomaly_code
`

